theme.css:
#search-box,#search-results,.search-mode-tabs,#fx-panel,#playlist-panel,#toast,.modal,.track-detail-modal,.cover-color-pop,.color-lab-pop,.visual-guide-card,.volume-popover,.quality-popover,.mini-queue-popover,.home-hero,.home-card,.home-tile,.home-mosaic-cell,.pl-inline-detail{background:linear-gradient(145deg,rgba(var(--home-accent-rgb),.12),rgba(234,241,247,0.88) 44%,rgba(220,231,240,0.86))!important;border-color:rgba(53,83,106,0.18)!important;box-shadow:var(--th-panel-shadow)!important}
#search-box,#search-results,.search-mode-tabs{background:rgba(234,241,247,.78)!important}
#playlist-panel{background:linear-gradient(145deg,rgba(var(--home-accent-rgb),.10),rgba(234,241,247,0.9) 44%,rgba(220,231,240,0.88))!important}
.search-empty{color:rgba(70,94,110,0.7)!important}
.playlist-source-head b,.playlist-source-option-name{color:rgba(27,49,65,0.98)!important;text-shadow:none!important}
.playlist-source-head span,.playlist-source-option-sub,.playlist-source-manage{color:rgba(69,91,106,0.78)!important}
.playlist-source-option{background:rgba(255,255,255,.92)!important;border-color:rgba(53,83,106,0.18)!important}
.playlist-source-option:hover{background:rgba(225,237,245,.96)!important;border-color:rgba(53,83,106,0.3)!important}
.home-hero,.home-card,.home-tile,.home-mosaic-cell{background:linear-gradient(145deg,rgba(var(--home-accent-rgb),.12),rgba(234,241,247,0.88) 44%,rgba(220,231,240,0.86))!important;border-color:rgba(53,83,106,0.18)!important}
.home-card-title,.home-tile-title,.home-title,.home-section-title,.home-local-action{color:rgba(27,49,65,0.98)!important}
.home-card-sub,.home-tile-sub,.home-sub,.home-section-note,.home-weather-pill{color:rgba(69,91,106,0.82)!important}
.home-card-label,.home-kicker{color:rgba(47,113,142,0.96)!important}
:root{color-scheme:light}
html,body{background:linear-gradient(145deg,#f8fbff,#eaf1f7 55%,#dce7f0)!important;color:rgba(27,49,65,0.92)!important}
:root #desktop-titlebar,:root .desktop-drag-region,:root .desktop-app-title{color:rgba(27,49,65,0.86)!important}
:root .desktop-mode-btn,:root .desktop-window-btn,:root #desktop-titlebar #update-entry{color:rgba(27,49,65,0.82)!important;background:rgba(234,241,247,0.7)!important;border-color:rgba(53,83,106,0.2)!important}
:root #search-input{color:rgba(27,49,65,0.96)!important}
:root #search-input::placeholder{color:rgba(69,91,106,0.58)!important}
:root #search-icon{color:rgba(69,91,106,0.72)!important}
:root .search-mode-tabs button{color:rgba(69,91,106,0.82)!important}
:root .search-mode-tabs button:hover{color:rgba(27,49,65,0.96)!important}
:root .search-result-title,:root .search-result-meta,:root .search-history-head,:root .search-history-chip{color:rgba(27,49,65,0.88)!important}
:root .search-result-meta,:root .search-history-head{color:rgba(69,91,106,0.78)!important}
:root .search-artist-link{color:rgba(47,113,142,0.98)!important}
:root .search-result .add-btn,:root .podcast-back-btn,:root .icon-btn,:root .home-chip,:root .modal-btn,:root .fx-mini-btn,:root .fx-toggle,:root .fx-seg button,:root .panel-tab,:root .preset-card,:root .quality-option,:root .lyric-color-row,:root .visual-guide-actions button{color:rgba(27,49,65,0.84)!important}
:root .icon-btn:hover,:root .home-chip:hover,:root .modal-btn:hover,:root .fx-mini-btn:hover,:root .fx-toggle:hover,:root .fx-seg button:hover,:root .panel-tab:hover,:root .preset-card:hover,:root .quality-option:hover{color:rgba(27,49,65,0.98)!important}
:root #upload-btn,:root #home-btn,:root #visual-guide-btn,:root .top-account-name,:root #user-btn{color:rgba(27,49,65,0.88)!important}
:root #thumb-title,:root #thumb-artist,:root .control-title,:root .control-artist,:root .ctrl-btn{color:rgba(27,49,65,0.9)!important}
:root .fx-title,:root .fx-sub,:root .fx-fold-head,:root .fx-fold-title strong,:root .fx-fold-title small,:root .fx-advanced-head,:root .fx-slider label,:root .fx-slider output,:root .fx-color-row-label,:root .fx-color-row-label small,:root .fx-mini-player-settings-head strong,:root .fx-mini-player-settings-head small{color:rgba(27,49,65,0.82)!important}
:root .fx-sub,:root .fx-fold-title small,:root .fx-slider output,:root .fx-color-row-label small,:root .fx-mini-player-settings-head small{color:rgba(69,91,106,0.78)!important}
:root .preset-card .pc-name,:root .user-archive-name,:root .plugin-item-title,:root .plugin-item-meta,:root .plugin-item-hosts,:root .collect-title,:root .playlist-delete-name,:root .qi-name,:root .pl-name,:root .pl-detail-title,:root .pl-detail-row-title,:root .detail-title,:root .artist-song-name,:root .local-beat-track-title,:root .custom-lyric-title{color:rgba(27,49,65,0.92)!important}
:root .preset-card .pc-desc,:root .user-archive-meta,:root .plugin-item-meta,:root .plugin-item-hosts,:root .qi-sub,:root .pl-sub,:root .pl-detail-sub,:root .pl-detail-count,:root .detail-sub,:root .detail-k,:root .detail-v,:root .artist-song-meta,:root .local-beat-track-sub,:root .custom-lyric-sub,:root .comment-meta,:root .comment-text,:root .local-beat-desc,:root .local-playlist-empty-hint{color:rgba(69,91,106,0.78)!important}
:root .custom-lyric-input,:root .color-lab-hex,:root .user-archive-input{color:rgba(27,49,65,0.94)!important;background:rgba(255,255,255,0.88)!important;border-color:rgba(53,83,106,0.28)!important}
:root .custom-lyric-input::placeholder{color:rgba(69,91,106,0.56)!important}
:root #toast,:root .source-fallback-body,:root .source-fallback-title{color:rgba(27,49,65,0.9)!important}
:root .update-item-text,:root .visual-guide-title,:root .visual-guide-body,:root .visual-guide-progress,:root .gesture-hud,:root .gesture-confirm,:root .gesture-legend{color:rgba(27,49,65,0.84)!important}
:root .plugin-item-kind{color:rgba(47,113,142,0.98)!important}
:root .panel-tab.active,:root .queue-item.now,:root .mini-queue-item.now,:root .preset-card.active,:root .fx-toggle.on,:root .fx-seg button.active,:root #search-mode-tabs button.active{color:#fff!important}
:root .tag-podcast{color:rgba(27,49,65,0.78)!important;background:rgba(237,245,250,0.9)!important}
:root #bottom-bar .ctrl-btn:hover,:root #play-btn:hover{color:rgba(27,49,65,0.98)!important}
